def split_line(line):
    """Splits one line of comma-separated text into its fields.

    A comma inside double quotes does not split the field. The quotes are
    dropped, and a doubled quote inside a quoted part stands for one quote.
    Spaces around unquoted text are stripped; quoted text is kept as is.
    """
    fields = []
    buf = []          # characters of the current field
    keep = 0          # length of buf up to the last quoted character
    in_quotes = False
    i = 0
    n = len(line)
    while i < n:
        ch = line[i]
        if in_quotes:
            if ch == '"':
                if i + 1 < n and line[i + 1] == '"':
                    buf.append('"')
                    i += 1
                else:
                    in_quotes = False
                keep = len(buf)
            else:
                buf.append(ch)
                keep = len(buf)
        elif ch == '"':
            in_quotes = True
            # drop unquoted leading spaces before the opening quote
            if not "".join(buf).strip():
                buf = []
            keep = len(buf)
        elif ch == ",":
            fields.append(_finish(buf, keep))
            buf, keep = [], 0
        else:
            buf.append(ch)
        i += 1
    fields.append(_finish(buf, keep))
    return fields


def _finish(buf, keep):
    text = "".join(buf)
    # strip spaces only outside quoted characters
    head, tail = text[:keep], text[keep:]
    if keep == 0:
        return tail.strip()
    return head + tail.rstrip()

files.tests/test_csvline.py:
from csvline import split_line


def test_plain_fields():
    assert split_line("a,b,c") == ["a", "b", "c"]


def test_strips_spaces():
    assert split_line("a , b") == ["a", "b"]


def test_comma_inside_quotes_stays_in_field():
    assert split_line('a,"b,c",d') == ["a", "b,c", "d"]


def test_address_with_comma():
    assert split_line('Bob,"12 High St, Leeds"') == ["Bob", "12 High St, Leeds"]


def test_doubled_quote_is_one_quote():
    assert split_line('a,"say ""hi""",b') == ["a", 'say "hi"', "b"]


def test_spaces_around_quoted_field_are_stripped():
    assert split_line('a , "b,c" ,d') == ["a", "b,c", "d"]


def test_empty_quoted_field():
    assert split_line('a,"",b') == ["a", "", "b"]

